import{_ as a,o,c as r,a3 as e}from"./chunks/framework.CqzWVxDX.js";const i="/ems_simulate/assets/data-monitor-read.CzSLJ_0X.png",l="/ems_simulate/assets/data-monitor-history.Cm4NU0fi.png",m=JSON.parse('{"title":"数据监视","description":"","frontmatter":{},"headers":[],"relativePath":"guide/simulation/data-monitor.md","filePath":"guide/simulation/data-monitor.md","lastUpdated":1787449307000}'),n={name:"guide/simulation/data-monitor.md"};function s(d,t,u,h,c,p){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="数据监视" tabindex="-1">数据监视 <a class="header-anchor" href="#数据监视" aria-label="Permalink to &quot;数据监视&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>配置完测点后，即可在设备详情中<strong>实时监视</strong>测点数据的变化。EMS Simulate 提供多层级的数据监视能力：读取（单点/批量/自动）、数据模拟、测点映射、变化追踪与报文查看。</p><h2 id="二、读取测点数据" tabindex="-1">二、读取测点数据 <a class="header-anchor" href="#二、读取测点数据" aria-label="Permalink to &quot;二、读取测点数据&quot;">​</a></h2><h3 id="单点读取" tabindex="-1">单点读取 <a class="header-anchor" href="#单点读取" aria-label="Permalink to &quot;单点读取&quot;">​</a></h3><p>在测点表格中点击行的&quot;<strong>读取</strong>&quot;按钮，向设备（或对端）发起一次读取，返回最新值并更新&quot;真实值&quot;列。</p><h3 id="批量读取" tabindex="-1">批量读取 <a class="header-anchor" href="#批量读取" aria-label="Permalink to &quot;批量读取&quot;">​</a></h3><p>点击“<strong>批量读取</strong>”后，前端只提交一次后台读取任务；后端将<strong>连续地址</strong>的测点合并读取（如 Modbus 一次读取多个寄存器），非连续地址自动拆分为多次。前端后续查询的是任务状态，不会通过定时请求重复触发设备读取。</p><h3 id="自动读取" tabindex="-1">自动读取 <a class="header-anchor" href="#自动读取" aria-label="Permalink to &quot;自动读取&quot;">​</a></h3><p>点击“<strong>自动读取</strong>”后，读取任务由后端按设置的轮询周期持续执行，支持批量、逐点以及 IEC 61850 DataSet 模式。切换页面不会中断任务；再次进入设备页面时会从后端恢复开关和模式状态。点击关闭开关会显式取消任务，设备停止、删除或应用退出时也会自动清理。</p><p>自动读取不显示进度条，只通过开关和当前模式标签表示运行状态；进度条仅用于用户主动发起的手动批量/逐点读取。</p><p>批量/DataSet 模式设置的是<strong>轮询周期</strong>；逐点模式设置的是相邻测点请求的<strong>点间隔</strong>，完整一轮结束后至少等待 1 秒再开始下一轮。页面刷新只展示后端缓存，不会额外触发设备读取。</p><p><img src="'+i+'" alt=""></p><blockquote><p>测点表格中的读取/批量读取/自动读取操作与返回结果。</p></blockquote><h2 id="三、模拟配置" tabindex="-1">三、模拟配置 <a class="header-anchor" href="#三、模拟配置" aria-label="Permalink to &quot;三、模拟配置&quot;">​</a></h2><p>开启设备后，可通过&quot;<strong>模拟配置</strong>&quot;功能配置哪些测点参与模拟、每个测点的模拟方式（随机 / 自增 / 自减 / 正弦波 / 斜坡 / 脉冲），并在&quot;模拟数据&quot;页签中实时监视与启停模拟。</p><blockquote><p>⚠️ 必须先<strong>开启设备</strong>，&quot;模拟配置&quot;按钮才可用。</p></blockquote><blockquote><p>📄 详细配置步骤见 <a href="./point-config.html">测点配置（模拟配置）</a>。</p></blockquote><h2 id="四、测点映射与公式" tabindex="-1">四、测点映射与公式 <a class="header-anchor" href="#四、测点映射与公式" aria-label="Permalink to &quot;四、测点映射与公式&quot;">​</a></h2><ul><li><strong>测点映射</strong>：将一个测点的值联动到另一个测点（跨设备数据镜像），源测点变化时目标测点自动更新；</li><li><strong>公式计算</strong>：映射值支持公式，如 <code>视在功率 = √(有功² + 无功²)</code>，实现基于多测点的派生数据；</li><li>映射关系在&quot;测点映射&quot;面板中配置，可查看所有映射与来源设备。</li></ul><h2 id="五、变化追踪" tabindex="-1">五、变化追踪 <a class="header-anchor" href="#五、变化追踪" aria-label="Permalink to &quot;五、变化追踪&quot;">​</a></h2><p>打开测点的&quot;<strong>变化历史</strong>&quot;，可查看该测点每次值变化的时间、旧值/新值与<strong>变化原因</strong>：</p><table tabindex="0"><thead><tr><th>变化原因</th><th>说明</th></tr></thead><tbody><tr><td>手动</td><td>手动修改真实值</td></tr><tr><td>模拟</td><td>数据模拟驱动</td></tr><tr><td>映射</td><td>测点映射联动</td></tr><tr><td>协议写入</td><td>对端通过协议写入</td></tr><tr><td>客户端读取</td><td>客户端模式读取到的新值</td></tr></tbody></table><p><img src="'+l+'" alt=""></p><blockquote><p>测点变化历史列表（时间、值、变化原因）。</p></blockquote><blockquote><p>💡 变化追踪便于排查&quot;数据从哪来、为什么变&quot;，是联调排查的利器。</p></blockquote><h2 id="六、报文查看" tabindex="-1">六、报文查看 <a class="header-anchor" href="#六、报文查看" aria-label="Permalink to &quot;六、报文查看&quot;">​</a></h2><p>点击设备右上角的&quot;<strong>报文</strong>&quot;图标，实时查看该设备与对端交互的原始报文（请求帧/响应帧、发送/接收方向、字段解析）。报文查看是协议级监视手段，与测点级监视互补：</p><ul><li>各协议报文结构详解见<a href="./../protocols/">协议支持</a>；</li><li>报文窗口支持暂停刷新、按方向/从机筛选、报文详情与原始字节定位。</li></ul><h2 id="七、注意事项" tabindex="-1">七、注意事项 <a class="header-anchor" href="#七、注意事项" aria-label="Permalink to &quot;七、注意事项&quot;">​</a></h2><ul><li>自动读取与模拟同时开启时，模拟值会持续覆盖真实值，读取结果以最新一次为准；</li><li>自动读取属于当前设备连接会话，后端或应用重启后不会自动恢复；</li><li>批量读取合并连续地址需同功能码/同解析码；</li><li>变化历史记录数量有限（按最新 N 条展示），如需长期留档请结合数据库存储。</li></ul>',31)])])}const b=a(n,[["render",s]]);export{m as __pageData,b as default};
